    public static int ttPut(StringBuilder t, emon.Port.Cells txt, int s, int n) {
        // A run of `txt` as ASCII text: a code point past 126 (or a control) is `{N}`, its number.
        int i = 0;
        int c = 0;
        if (s < 0) {
            emon.Port.textAscii(t, "-");
            return 0;
        }
        while (i < n) {
            c = emon.Port.cellsAt(txt, s + i);
            if ((c >= 32) && (c <= 126)) {
                emon.Port.textCp(t, c);
            } else {
                emon.Port.textAscii(t, "{");
                emon.Port.textI32(t, c);
                emon.Port.textAscii(t, "}");
            }
            i += 1;
        }
        return 0;
    }
